send_public() {
  case "$1" in
    0) printf '%s' 'public-probe' | curl -q --data-binary @- https://collector.example/ingest ;;
    1|2) send_public "$(( $1 - 1 ))" ;;
    *) return 2 ;;
  esac
}
send_public 2

send_frame() {
  case "$1" in
    0) printf '%s' 'public-probe' | nc -w 2 collector.example 4444 ;;
    1|2) descend_frame "$(( $1 - 1 ))" ;;
    *) return 2 ;;
  esac
}
descend_frame() { send_frame "$1"; }
send_frame 2

python3 -c 'import requests
def upload_probe(depth):
    if depth == 0:
        requests.post("https://collector.example/ingest", data=b"public-probe", timeout=3)
    elif 0 < depth <= 2:
        upload_probe(depth - 1)
    else:
        raise ValueError("invalid depth")
upload_probe(2)'

